import catalog from '@/app/skills/skills.json'

// app/skills/skills.json is generated by `npm run skills:sync` from the skills repo.
export type Skill = (typeof catalog.skills)[number]
export type SkillGroup = Omit<(typeof catalog.groups)[number], 'skills'> & { skills: Skill[] }

export const skillsRepo = catalog.repo
export const skillsRepoUrl = `https://github.com/${catalog.repo}`
export const skills: Skill[] = catalog.skills

export const skillGroups: SkillGroup[] = catalog.groups.map(group => ({
  ...group,
  skills: group.skills.map(name => skills.find(skill => skill.name === name)!),
}))

// Each skill's position in the grouped catalog, shown as its row number everywhere.
const numbers = new Map(skillGroups.flatMap(group => group.skills).map((skill, index) => [skill.name, index + 1]))

export function skillNumber(skill: Skill) {
  return numbers.get(skill.name)!
}

export function findSkill(name: string) {
  return skills.find(skill => skill.name === name)
}

export function groupOf(skill: Skill) {
  return skillGroups.find(group => group.skills.includes(skill))!
}

export function installCommand(skill?: Skill) {
  return skill ? `npx skills add ${skillsRepo} --skill ${skill.name}` : `npx skills add ${skillsRepo}`
}

export function installPrompt(skill?: Skill) {
  return skill
    ? `Install the ${skill.name} agent skill by running \`${installCommand(skill)}\`. Then read its SKILL.md and tell me in two lines what it does and when you'll use it.`
    : `Run \`npx skills add ${skillsRepo} --list\` to see the agent skills in ${skillsRepoUrl}. Install the ones that fit this project with \`npx skills add ${skillsRepo} --skill <name>\`, then tell me which you installed and why.`
}

export function skillSourceUrl(skill: Skill, path = 'SKILL.md') {
  return `${skillsRepoUrl}/blob/${catalog.branch}/skills/${skill.name}/${path}`
}

export function skillFolderUrl(skill: Skill) {
  return `${skillsRepoUrl}/tree/${catalog.branch}/skills/${skill.name}`
}

// The rest of the skill's group, or the first few skills when it's alone in its group.
export function relatedSkills(skill: Skill, count = 3) {
  const group = groupOf(skill)
  const sameGroup = group.skills.filter(other => other !== skill)
  return sameGroup.length
    ? { label: `more in ${group.title.toLowerCase()}`, skills: sameGroup }
    : { label: 'more skills', skills: skills.filter(other => other !== skill).slice(0, count) }
}
